+// In-memory note store. One instance per server. Deleted notes stay in the trash for 30 days.
+export function createStore({ now = Date.now } = {}) {
   const notes = [];
   let nextId = 1;
+  // Expired trash is dropped lazily, on the next access.
+  const sweep = () => {
