       return true;
     },
+    trash(owner) {
+      sweep();
+      return notes.filter((n) => n.deletedAt && n.owner === owner);
+    },
+    restore(id, owner) {
+      sweep();
+      const note = notes.find((n) => n.id === id && n.deletedAt && n.owner === owner);
+      if (note) delete note.deletedAt;
+      return note;
+    },
   };
 }
diff --git a/tests/trash.test.mjs b/tests/trash.test.mjs
new file mode 100644
index 0000000..f5fb763
--- /dev/null
+++ b/tests/trash.test.mjs
@@ -0,0 +1,76 @@
+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/app/server.js';
+
+const DAY = 24 * 60 * 60 * 1000;
+let server, base, clock = Date.parse('2026-01-01T00:00:00Z');
+before(async () => {
+  server = createApp({ now: () => clock }).listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+after(() => server.close());
+
+const call = (method, path, user, body) => fetch(base + path, {
+  method, headers: { 'content-type': 'application/json', ...(user ? { 'x-user': user } : {}) }, body: body && JSON.stringify(body),
+});
+const make = async (user, title) => (await call('POST', '/notes', user, { title })).json();
+const trashed = async (user) => (await (await call('GET', '/trash', user)).json()).map((n) => n.id);
+
+test('T-01.1 a deleted note leaves the list and appears in the trash', async () => {
+  const n = await make('ayse', 'sil');
+  assert.equal((await call('DELETE', `/notes/${n.id}`, 'ayse')).status, 204);
+  assert.equal((await call('GET', `/notes/${n.id}`, 'ayse')).status, 404);
+  assert.ok(!(await (await call('GET', '/notes', 'ayse')).json()).some((x) => x.id === n.id));
+  assert.ok((await trashed('ayse')).includes(n.id));
+});
+
+test('T-01.2 restore brings the note back and empties it from the trash', async () => {
+  const n = await make('ayse', 'geri');
+  await call('DELETE', `/notes/${n.id}`, 'ayse');
+  const r = await call('POST', `/notes/${n.id}/restore`, 'ayse');
+  assert.equal(r.status, 200);
+  const back = await r.json();
+  assert.equal(back.title, 'geri');
+  assert.equal(back.deletedAt, undefined);
+  assert.equal((await call('GET', `/notes/${n.id}`, 'ayse')).status, 200);
+  assert.ok(!(await trashed('ayse')).includes(n.id));
+});
+
+test('T-01.3 a note deleted more than 30 days ago cannot be restored or listed', async () => {
+  const n = await make('ayse', 'eski');
+  await call('DELETE', `/notes/${n.id}`, 'ayse');
+  clock += 30 * DAY;
+  assert.equal((await call('POST', `/notes/${n.id}/restore`, 'ayse')).status, 200, 'exactly 30 days still works');
+  await call('DELETE', `/notes/${n.id}`, 'ayse');
+  clock += 30 * DAY + 1;
+  assert.ok(!(await trashed('ayse')).includes(n.id));
+  assert.equal((await call('POST', `/notes/${n.id}/restore`, 'ayse')).status, 404);
+  assert.equal((await call('GET', `/notes/${n.id}`, 'ayse')).status, 404);
+});
+
+test('T-01.4 restoring a note that is not in the trash is 404', async () => {
+  const n = await make('ayse', 'canlı');
+  assert.equal((await call('POST', `/notes/${n.id}/restore`, 'ayse')).status, 404);
+  assert.equal((await call('POST', '/notes/yok/restore', 'ayse')).status, 404);
+});
+
+test('T-01.5 attacker: another user cannot see or restore my trashed note', async () => {
+  const n = await make('ayse', 'gizli');
+  await call('DELETE', `/notes/${n.id}`, 'ayse');
+  assert.ok(!(await trashed('mehmet')).includes(n.id));
+  assert.equal((await call('POST', `/notes/${n.id}/restore`, 'mehmet')).status, 404);
+  assert.ok((await trashed('ayse')).includes(n.id), 'still in the owner trash');
+});
+
+test('T-01.6 trash and restore need a user', async () => {
+  assert.equal((await call('GET', '/trash')).status, 401);
+  assert.equal((await call('POST', '/notes/1/restore')).status, 401);
+});
+
+test('T-01.7 a trashed note cannot be edited or deleted again', async () => {
+  const n = await make('ayse', 'ölü');
+  await call('DELETE', `/notes/${n.id}`, 'ayse');
+  assert.equal((await call('PATCH', `/notes/${n.id}`, 'ayse', { title: 'x' })).status, 404);
+  assert.equal((await call('DELETE', `/notes/${n.id}`, 'ayse')).status, 404);
+});

