+  const s = createApp({ now: () => t }).listen(0);
+  await new Promise((r) => s.once('listening', r));
+  const c = (m, p, body) => fetch(`http://127.0.0.1:${s.address().port}${p}`, {
+    method: m, headers: { 'content-type': 'application/json', 'x-user': 'ayse' }, body: body && JSON.stringify(body),
+  });
+  try {
+    const a = await (await c('POST', '/notes', { title: 'Eski' })).json();
+    const b = await (await c('POST', '/notes', { title: 'Eski 2' })).json();
+    await c('DELETE', `/notes/${a.id}`);
+    await c('DELETE', `/notes/${b.id}`);
+    t += 29 * 86400000;
+    assert.equal((await (await c('GET', '/trash')).json()).length, 2);
+    t += 2 * 86400000;
+    assert.equal((await c('POST', `/notes/${a.id}/restore`)).status, 410);
+    assert.equal((await (await c('GET', '/trash')).json()).length, 0);
+  } finally { s.close(); }
+});
